import React, {useState} from "react";
import api from "../api";

export default function Contact(){
  const [form,setForm] = useState({name:"",email:"",phone:"",message:""});
  const [status,setStatus] = useState("");

  const change = e => setForm(f=>({...f,[e.target.name]:e.target.value}));

  const submit = async (e) => {
    e.preventDefault();
    setStatus("Sending...");
    try{
      const res = await api.post("/contact", form); // backend route /api/contact
      setStatus("Message sent. Thank you!");
      setForm({name:"",email:"",phone:"",message:""});
    }catch(err){
      console.error(err);
      setStatus("Failed to send. Try again later.");
    }
  }

  return (
    <div className="container">
      <div className="card">
        <h2 style={{color:"#005baa"}}>Contact Us</h2>
        <form onSubmit={submit} style={{marginTop:12}}>
          <input className="form-control" name="name" placeholder="Your Name" value={form.name} onChange={change} required/>
          <input className="form-control" name="email" placeholder="Your Email" type="email" value={form.email} onChange={change} required/>
          <input className="form-control" name="phone" placeholder="Phone" value={form.phone} onChange={change}/>
          <textarea className="form-control" name="message" placeholder="Message" value={form.message} onChange={change} required/>
          <button className="btn" type="submit">Send</button>
          <div style={{marginTop:8}}>{status}</div>
        </form>

        <iframe className="map" title="map"
          src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d..."></iframe>
      </div>
    </div>
  );
}
